// The label is a silver disc inside a black ring over a blue field. Both edges are circles
// printed on the label (measured on the packshot: radii 57.3 and 87.2 units), so on the can
// they are seen wrapped round a cylinder of radius 45.
const onCan = u => r2(100 + 45 * Math.sin(Math.max(-1.5707, Math.min(1.5707, u / 45))));
const rcDisc = (() => {
  const cy = 81.3, r = 57.3; let d = '';
  for (let i = 0; i < 72; i++) { const t = i * Math.PI / 36; d += `${i ? 'L' : 'M'}${onCan(r * Math.sin(t))} ${r2(cy - r * Math.cos(t))}`; }
  return d + 'Z';
})();
const rcBlue = (() => {
  const cy = 73.3, r = 87.2; let d = '';
  for (let i = 0; i <= 40; i++) { const u = -70.6 + i * 3.53; d += `${i ? 'L' : 'M'}${onCan(u)} ${r2(cy + Math.sqrt(r * r - u * u))}`; }
  return d + 'V240H55Z';
})();
